package com.vajjha.recipes.controller;
import com.fasterxml.jackson.databind.JsonNode;import com.fasterxml.jackson.databind.ObjectMapper;import com.fasterxml.jackson.databind.node.JsonNodeFactory;import com.vajjha.recipes.model.Recipe;import com.vajjha.recipes.model.RecipeCategory;import com.vajjha.recipes.repository.CategoryRepository;import com.vajjha.recipes.repository.RecipeRepository;import jakarta.validation.Valid;import jakarta.validation.constraints.NotBlank;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.text.Normalizer;import java.util.*;
@RestController @RequestMapping("/api") public class RecipeController{
 private final RecipeRepository recipes;private final CategoryRepository categories;private final ObjectMapper mapper;
 public RecipeController(RecipeRepository r,CategoryRepository c,ObjectMapper m){recipes=r;categories=c;mapper=m;}
 @GetMapping("/health")public Map<String,String>health(){return Map.of("status","ok","service","recipes-api");}
 @GetMapping("/categories")public List<RecipeCategory>categories(){return categories.findAll();}
 @GetMapping("/recipes")public List<Map<String,Object>>all(@RequestParam(required=false)Long categoryId,@RequestParam(required=false)Boolean favorites,@RequestParam(required=false)String q){List<Recipe>rows=categoryId==null?recipes.findAllByOrderByCreatedAtDesc():recipes.findByCategoryIdOrderByCreatedAtDesc(categoryId);return rows.stream().filter(r->favorites==null||!favorites||r.isFavorite()).filter(r->q==null||q.isBlank()||(r.getTitle()+" "+Objects.toString(r.getDescription(),"")).toLowerCase(Locale.ROOT).contains(q.toLowerCase(Locale.ROOT))).map(this::view).toList();}
 @GetMapping("/recipes/{id}")public Map<String,Object>one(@PathVariable Long id){return view(find(id));}
 @PostMapping("/recipes")@ResponseStatus(HttpStatus.CREATED)public Map<String,Object>create(@Valid @RequestBody RecipeInput in){Recipe r=new Recipe();apply(r,in);return view(recipes.save(r));}
 @PutMapping("/recipes/{id}")public Map<String,Object>update(@PathVariable Long id,@Valid @RequestBody RecipeInput in){Recipe r=find(id);apply(r,in);return view(recipes.save(r));}
 @PatchMapping("/recipes/{id}/favorite")public Map<String,Object>favorite(@PathVariable Long id){Recipe r=find(id);r.setFavorite(!r.isFavorite());return view(recipes.save(r));}
 @DeleteMapping("/recipes/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(@PathVariable Long id){recipes.delete(find(id));}
 private Recipe find(Long id){return recipes.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Recipe not found"));}
 private void apply(Recipe r,RecipeInput i){r.setTitle(i.title().trim());r.setSlug(slug(i.title())+"-"+(r.getId()==null?UUID.randomUUID().toString().substring(0,8):r.getId()));r.setDescription(i.description());r.setImageUrl(i.imageUrl());r.setPrepMinutes(i.prepMinutes()==null?0:i.prepMinutes());r.setCookMinutes(i.cookMinutes()==null?0:i.cookMinutes());r.setServings(i.servings()==null?2:i.servings());r.setDifficulty(i.difficulty()==null?"EASY":i.difficulty().toUpperCase(Locale.ROOT));r.setCuisine(i.cuisine());Long cid=i.categoryId();if(cid==null&&i.category()!=null)cid=categories.findByNameIgnoreCase(i.category()).map(RecipeCategory::getId).orElse(null);r.setCategoryId(cid);r.setIngredients(node(i.ingredients()));r.setInstructions(node(i.instructions()));r.setTags(node(i.tags()));if(r.getId()==null)r.setPublished(true);}
 private JsonNode node(Object v){return v==null?JsonNodeFactory.instance.arrayNode():mapper.valueToTree(v);}
 private String slug(String s){return Normalizer.normalize(s,Normalizer.Form.NFD).replaceAll("\\p{M}","").toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+","-").replaceAll("(^-|-$)","");}
 private String prettyDifficulty(String value){if(value==null||value.isBlank())return "Easy";return value.substring(0,1).toUpperCase(Locale.ROOT)+value.substring(1).toLowerCase(Locale.ROOT);}
 private Map<String,Object>view(Recipe r){RecipeCategory c=r.getCategoryId()==null?null:categories.findById(r.getCategoryId()).orElse(null);Map<String,Object>m=new LinkedHashMap<>();m.put("id",r.getId());m.put("title",r.getTitle());m.put("slug",r.getSlug());m.put("description",Objects.toString(r.getDescription(),""));m.put("imageUrl",Objects.toString(r.getImageUrl(),""));m.put("prepMinutes",Objects.requireNonNullElse(r.getPrepMinutes(),0));m.put("cookMinutes",Objects.requireNonNullElse(r.getCookMinutes(),0));m.put("servings",Objects.requireNonNullElse(r.getServings(),2));m.put("difficulty",prettyDifficulty(r.getDifficulty()));m.put("cuisine",Objects.toString(r.getCuisine(),""));m.put("ingredients",r.getIngredients()==null?JsonNodeFactory.instance.arrayNode():r.getIngredients());m.put("instructions",r.getInstructions()==null?JsonNodeFactory.instance.arrayNode():r.getInstructions());m.put("tags",r.getTags()==null?JsonNodeFactory.instance.arrayNode():r.getTags());m.put("isFavorite",r.isFavorite());m.put("category",c==null?"Unsorted":c.getName());m.put("categoryId",r.getCategoryId());return m;}
 public record RecipeInput(@NotBlank String title,String description,String imageUrl,Integer prepMinutes,Integer cookMinutes,Integer servings,String difficulty,String cuisine,Long categoryId,String category,Object ingredients,Object instructions,Object tags){}
}